# ============================================================================
# bash-pre-snapshot.ps1
# Auto-generated by CodeAgentSwarm - Do not edit manually
#
# PreToolUse hook: Captures file state BEFORE Bash command modifies it
# PowerShell version for Windows compatibility
# ============================================================================

$WebhookPort = if ($env:CODEAGENTSWARM_WEBHOOK_PORT) { $env:CODEAGENTSWARM_WEBHOOK_PORT } else { "45782" }
$TerminalId = if ($env:CODEAGENTSWARM_CURRENT_QUADRANT) { $env:CODEAGENTSWARM_CURRENT_QUADRANT } else { "0" }

# Optional debug logging — OFF unless CODEAGENTSWARM_HOOK_DEBUG is set, so the log can never
# grow unbounded in normal use (it once reached ~5 GB).
$DebugLog = Join-Path $env:USERPROFILE ".codeagentswarm\hooks\debug.log"
$Timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
function Write-DebugLog($msg) { if ($env:CODEAGENTSWARM_HOOK_DEBUG) { Add-Content -Path $DebugLog -Value "[$Timestamp] $msg" } }
Write-DebugLog "PRE-SNAPSHOT called (PowerShell)"

try {
    
# Async reads enforce a deadline even when the producer leaves stdin open.
$InputStream = [Console]::OpenStandardInput()
$InputBuffer = New-Object byte[] 65536
$InputBytes = New-Object IO.MemoryStream
$InputClock = [Diagnostics.Stopwatch]::StartNew()
try {
    while ($true) {
        $Remaining = 5000 - [int]$InputClock.ElapsedMilliseconds
        if ($Remaining -le 0) { exit 0 }
        $Read = $InputStream.ReadAsync($InputBuffer, 0, $InputBuffer.Length)
        if (-not $Read.Wait($Remaining)) { exit 0 }
        $Count = $Read.Result
        if ($Count -eq 0) { break }
        if ($InputBytes.Length + $Count -gt 16777216) { exit 0 }
        $InputBytes.Write($InputBuffer, 0, $Count)
    }
    $InputBytes.Position = 0
} catch { exit 0 }

# .NET's streaming JSON reader skips stdout without constructing PowerShell objects.
# Quotas also bound selected strings, nesting and JSON member names.
Add-Type -AssemblyName System.Runtime.Serialization
$Quotas = New-Object System.Xml.XmlDictionaryReaderQuotas
$Quotas.MaxStringContentLength = 65536
$Reader = [System.Runtime.Serialization.Json.JsonReaderWriterFactory]::CreateJsonReader($InputBytes, $Quotas)
$Command = ''
$Cwd = ''
try {
    if (-not $Reader.Read() -or $Reader.GetAttribute('type') -ne 'object') { exit 0 }
    $Reader.Read() | Out-Null
    while ($Reader.NodeType -eq [Xml.XmlNodeType]::Element) {
        if ($Reader.LocalName -eq 'cwd' -and $Reader.GetAttribute('type') -eq 'string') {
            $Cwd = $Reader.ReadElementContentAsString()
        } elseif ($Reader.LocalName -eq 'tool_input' -and $Reader.GetAttribute('type') -eq 'object') {
            $Reader.Read() | Out-Null
            while ($Reader.NodeType -eq [Xml.XmlNodeType]::Element) {
                if ($Reader.LocalName -eq 'command' -and $Reader.GetAttribute('type') -eq 'string') {
                    $Command = $Reader.ReadElementContentAsString()
                } else { $Reader.Skip() }
            }
            $Reader.ReadEndElement()
        } else { $Reader.Skip() }
    }
    $Reader.ReadEndElement()
    if (-not $Reader.EOF) { exit 0 }
} catch { exit 0 } finally { $Reader.Close(); $InputBytes.Dispose() }

    
function Read-FileSnapshot([string]$FilePath) {
    $FileReader = [IO.File]::OpenText($FilePath)
    try {
        $FileSize = $FileReader.BaseStream.Length
        if ($FileSize -gt 1048576) { throw 'Snapshot too large' }
        $Chars = New-Object char[] ([int]$FileSize + 1)
        $Length = $FileReader.ReadBlock($Chars, 0, $Chars.Length)
        if ($Length -eq $Chars.Length -or $FileReader.BaseStream.Length -gt 1048576) { throw 'Snapshot grew during read' }
        # Native string: Get-Content adds provider metadata that PS 5.1 JSON expands.
        return [string]::new($Chars, 0, $Length)
    } finally { $FileReader.Dispose() }
}


    if (-not $Command) { exit 0 }

    # Detect target files from command
    function Get-TargetFiles {
        param([string]$Cmd)

        $Files = @()

        # Detect redirection patterns: echo/printf ... > file
        if ($Cmd -match '(?:echo|printf|cat).*?>\s*([^\s;&|]+)') {
            $Files += $Matches[1]
        }

        # Detect sed -i patterns
        if ($Cmd -match 'sed\s+-i.*?\s+([^\s;&|]+)$') {
            $Files += $Matches[1]
        }

        # Detect cp command
        if ($Cmd -match '^cp\s+.*?\s+([^\s;&|]+)$') {
            $Files += $Matches[1]
        }

        # Detect mv command (both source and dest)
        if ($Cmd -match '^mv\s+([^\s]+)\s+([^\s;&|]+)') {
            $Files += $Matches[1]
            $Files += $Matches[2]
        }

        # Detect rm command
        if ($Cmd -match '^rm\s+(?:-[^\s]+\s+)*([^\s;&|]+)') {
            $Files += $Matches[1]
        }

        # Detect tee command
        if ($Cmd -match 'tee\s+(?:-a\s+)?([^\s;&|]+)') {
            $Files += $Matches[1]
        }

        return $Files | Where-Object { $_ -and $_ -notmatch '[\$*?]' }
    }

    function Resolve-FilePath {
        param([string]$File, [string]$WorkingDir)

        if (-not $File) { return $null }

        # Remove quotes
        $File = $File -replace "^['`"]|['`"]$", ""

        # Resolve path
        if ([System.IO.Path]::IsPathRooted($File)) {
            return $File
        } else {
            return Join-Path $WorkingDir $File
        }
    }

    $TargetFiles = Get-TargetFiles -Cmd $Command
    if (-not $TargetFiles) { exit 0 }

    # Build JSON with file contents
    $FilesHash = @{}
    foreach ($File in $TargetFiles) {
        $FullPath = Resolve-FilePath -File $File -WorkingDir $Cwd
        if (-not $FullPath) { continue }

        try {
            $FullPath = [System.IO.Path]::GetFullPath($FullPath)
        } catch { continue }

        if (Test-Path -LiteralPath $FullPath -PathType Leaf) {
            try { $FilesHash[$FullPath] = Read-FileSnapshot $FullPath } catch { continue }
        } else {
            $FilesHash[$FullPath] = $null
        }
    }

    Write-DebugLog "PRE Sending - Files: $($FilesHash.Keys -join ', ')"

    # Send to webhook
    $Body = @{
        type = "bash_pre_snapshot"
        terminalId = $TerminalId
        command = $Command
        cwd = $Cwd
        files = $FilesHash
    } | ConvertTo-Json -Depth 2 -Compress

    try {
        Invoke-RestMethod -Uri "http://127.0.0.1:$WebhookPort/webhook" -Method POST -ContentType "application/json; charset=utf-8" -Body ([Text.Encoding]::UTF8.GetBytes($Body)) -TimeoutSec 2 | Out-Null
    } catch {
        Write-DebugLog "PRE Error: $_"
    }

} catch {
    Write-DebugLog "PRE Exception: $_"
}

exit 0
